// RB parity scenarios: invoices.ts, clients.ts, finance.ts, estimates.ts, spend.ts — every write route with valid and
// invalid bodies, allowed and denied users, plus the reads whose state they change. Called from parity.ts
// moduleScenarios() with its helpers (both = same call on the mock and the API; sides = side-specific path/body for
// ids generated by each side).
/* eslint-disable @typescript-eslint/no-explicit-any */
import { todayISO, addDays } from '@/domain/calendar'

type Res = { status: number; data?: any; warnings?: unknown; error?: { code: string; message: string; field?: string } }
type Pair = { m: Res; h: Res }
export interface RbHelpers {
  both: (label: string, who: string, method: string, path: string, body?: unknown, query?: Record<string, unknown>, ifMatch?: number) => Promise<Pair>
  sides: (label: string, who: string, method: string, path: (s: 'm' | 'h') => string, body: (s: 'm' | 'h') => unknown) => Promise<Pair | null>
  login: (who: string, email: string) => Promise<void>
  has: (who: string) => boolean
}

export async function rbScenarios(H: RbHelpers) {
  for (const who of ['subhankar', 'debasish', 'baishali', 'subham', 'jagannath', 'bijaya', 'rakesh', 'meera', 'sneha'])
    if (!H.has(who)) await H.login(who, who === 'rakesh' || who === 'meera' || who === 'sneha' ? `${who}@kalingasoft.in` : `${who}@seereon.co.in`)
  await rbInvoices(H)
  await rbFinance(H)
  await rbSpend(H)
  await rbClients(H)
  await rbEstimates(H)
}

const pick = (r: Pair | null, f: (d: any) => any) => (s: 'm' | 'h'): string => {
  const d = r ? (r[s] as Res).data : undefined
  return (d !== undefined && d !== null ? f(d) : undefined) ?? 'x'
}
const TODAY = () => todayISO()

/* ---------------------------------------------------------------- invoices ---------------------------------------------------------------- */
async function rbInvoices(H: RbHelpers) {
  const L = 'rb-invoices'
  const { both, sides } = H
  for (const who of ['santosh', 'priya', 'hritesh', 'ananya', 'debasish']) {
    await both(L, who, 'GET', '/finance/invoices')
    await both(L, who, 'GET', '/finance/invoices/meta')
    await both(L, who, 'GET', '/finance/invoices/settings')
  }
  for (const date of ['', '2027-04-01', 'bad', '2026-02-30']) await both(L, 'santosh', 'GET', '/finance/invoices/next-number', undefined, { date })
  for (const id of ['inv_ms_hrms_1', 'inv_ms_mgs_2', 'inv_ms_rcu_1', 'inv_draft_crm_cr1', 'nope']) await both(L, 'santosh', 'GET', `/finance/invoices/${id}`)
  await both(L, 'santosh', 'GET', '/finance/invoices/project-milestones', undefined, { project_id: 'p_hrms' })
  await both(L, 'santosh', 'GET', '/finance/invoices/project-milestones', undefined, { project_id: 'p_mgs', invoice_id: 'inv_ms_mgs_2' })
  await both(L, 'santosh', 'GET', '/finance/invoices/client-party', undefined, { client_id: 'cl_rcu' })
  await both(L, 'santosh', 'GET', '/finance/invoices/client-party', undefined, { client_id: 'nope' })
  for (const q of [{ project_id: 'p_hrms', from: '2026-04-01', to: TODAY() }, { project_id: 'p_dms', from: '2026-09-01', to: '2026-09-30' }, { project_id: 'p_hrms', from: 'x', to: 'y' }, { project_id: 'p_hrms', from: '2026-10-10', to: '2026-10-01' }])
    await both(L, 'santosh', 'GET', '/finance/invoices/billable-hours', undefined, q)
  await both(L, 'hritesh', 'GET', '/finance/invoices/prefill', undefined, { project_id: 'p_hrms' })
  await both(L, 'santosh', 'GET', '/finance/invoices/prefill', undefined, {})
  const pf = await both(L, 'santosh', 'GET', '/finance/invoices/prefill', undefined, { project_id: 'p_hrms', milestone_ids: 'ms_hrms_2,ms_hrms_3' })
  const draft = (pf.m.data as any)?.draft ?? {}
  // preview + validation
  await both(L, 'santosh', 'POST', '/finance/invoices/preview', draft)
  for (const v of [{ project_id: '' }, { milestone_ids: ['ms_hrms_1'] }, { seller: { ...draft.seller, gstin: '29AAKCS4821M1Z5' } }, { invoiced_on: '2099-01-01' }, { tds_pct: 25 },
    { lines: [{ item: '', hsn_sac: '12', qty: 0, rate_paise: -5, discount_pct: 101, gst_rate: 7 }] }, { number: 'SCI/26-27/0001' }, { bank: { ...draft.bank, ifsc: 'bad' } }])
    await both(L, 'santosh', 'POST', '/finance/invoices', { ...draft, ...v, issue: true })
  await both(L, 'hritesh', 'POST', '/finance/invoices', draft)
  // create draft -> patch -> issue -> TDS payments -> cancel blocked
  const cr = await both(L, 'santosh', 'POST', '/finance/invoices', draft)
  const iid = pick(cr, (d) => d.invoice?.id)
  await sides(L, 'santosh', 'PATCH', (s) => `/finance/invoices/${iid(s)}`, () => ({ ...draft, notes: 'Edited draft', po_reference: 'PO-77', reverse_charge: false }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/issue`, () => ({ number: 'sci/26-27/0001' }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/issue`, () => ({}))
  const det = await sides(L, 'santosh', 'GET', (s) => `/finance/invoices/${iid(s)}`, () => undefined)
  const total = (det?.m.data as any)?.invoice?.total_paise ?? 0
  const tds = (det?.m.data as any)?.suggested_tds_paise ?? 0
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/payments`, () => ({ received_paise: total * 2, paid_on: TODAY() }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/payments`, () => ({ received_paise: 100, tds_paise: 9e9, paid_on: TODAY() }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/payments`, () => ({ received_paise: Math.round(total / 3), tds_paise: Math.round(tds / 2), paid_on: TODAY(), reference: 'UTR-1', mode: 'NEFT' }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/cancel`, () => ({ reason: 'Client asked to cancel this' }))
  const det2 = await sides(L, 'santosh', 'GET', (s) => `/finance/invoices/${iid(s)}`, () => undefined)
  const bal = (det2?.m.data as any)?.balance_paise ?? 0
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/payments`, () => ({ received_paise: bal - Math.round(tds / 2), tds_paise: Math.round(tds / 2), paid_on: TODAY(), reference: 'UTR-2' }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/email`, () => ({ to: 'ap@mmg.in', cc: 'a@b.co; c@d.org', message: 'Please find the invoice attached.' }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${iid(s)}/duplicate`, () => ({}))
  // issue-at-once for an export client + an inter-state bill-to
  const pf2 = await both(L, 'santosh', 'GET', '/finance/invoices/prefill', undefined, { project_id: 'p_rcu', milestone_ids: 'ms_rcu_3' })
  await both(L, 'santosh', 'POST', '/finance/invoices', { ...((pf2.m.data as any)?.draft ?? {}), issue: true })
  const pf3 = await both(L, 'santosh', 'GET', '/finance/invoices/prefill', undefined, { project_id: 'p_crm', milestone_ids: 'ms_crm_1' })
  const d3 = (pf3.m.data as any)?.draft ?? {}
  const c3 = await both(L, 'santosh', 'POST', '/finance/invoices', {
    ...d3, issue: true, client_id: 'cl_infy', place_of_supply: '29', save_client: true,
    bill_to: { name: 'Infosys', address: 'Electronics City', city: 'Bengaluru', state: 'Karnataka', state_code: '29', pincode: '560100', country: 'India', gstin: '29AABCI1681G1ZF', pan: 'AABCI1681G', email: 'ap@infosys.com', phone: '', contact: 'AP' },
    lines: [{ id: 'a', item: 'Licences', description: '', hsn_sac: '997331', qty: 37, unit: 'Users', rate_paise: 123457, discount_pct: 12.5, gst_rate: 18, source: { kind: 'manual' } }, { id: 'b', item: 'Training', hsn_sac: '999293', qty: 2.5, unit: 'Days', rate_paise: 1500001, discount_pct: 0, gst_rate: 5 }],
  })
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${pick(c3, (d) => d.invoice?.id)(s)}/cancel`, () => ({ reason: 'short' }))
  await sides(L, 'santosh', 'POST', (s) => `/finance/invoices/${pick(c3, (d) => d.invoice?.id)(s)}/cancel`, () => ({ reason: 'Raised against the wrong PO' }))
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_ms_dms_1/cancel', { reason: 'Duplicate of an older invoice' })
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_ms_mgs_2/cancel', { reason: 'Has payments on it already' })
  await both(L, 'santosh', 'PATCH', '/finance/invoices/inv_ms_mgs_2', { notes: 'Thanks!', id: 'x' })
  await both(L, 'santosh', 'PATCH', '/finance/invoices/inv_ms_mgs_2', { notes: 'x', due_on: '2027-01-01' })
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_ms_mgs_2/payments', { received_paise: 100, paid_on: TODAY() }, undefined, 99)
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_ms_mgs_2/payments', { received_paise: 'abc', paid_on: TODAY() })
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_ms_mgs_2/email', { to: 'bad' })
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_draft_crm_cr1/email', {})
  await both(L, 'santosh', 'DELETE', '/finance/invoices/inv_ms_mgs_2')
  await both(L, 'santosh', 'DELETE', '/finance/invoices/inv_draft_crm_cr1', undefined, undefined, 7)
  await both(L, 'santosh', 'POST', '/finance/invoices/inv_draft_crm_cr1/duplicate')
  await both(L, 'santosh', 'DELETE', '/finance/invoices/inv_draft_crm_cr1')
  for (const body of [{ prefix: 'TOOLONG7' }, { payment_terms_days: 181 }, { default_gst_rate: 7 }, { bank: { account_number: '12 34' } }, { bank: { upi: 'a@1' } },
    { prefix: 'SEER', credit_note_prefix: 'cr', payment_terms_days: 15, default_gst_rate: '12', bank: { bank_name: ' ICICI ', account_number: '0011 2233 4455', ifsc: 'icic0000001', upi: 'pay@icici' }, signatory_name: ' S ' }])
    await both(L, 'santosh', 'PUT', '/finance/invoices/settings', body)
  await both(L, 'priya', 'PUT', '/finance/invoices/settings', { prefix: 'X' })
  await both(L, 'debasish', 'GET', '/finance/invoices/settings')
  await both(L, 'santosh', 'GET', '/finance/invoices/next-number')
  await both(L, 'santosh', 'GET', '/finance/invoices')
  await both(L, 'santosh', 'GET', '/master/org')
}

/* ---------------------------------------------------------------- finance ---------------------------------------------------------------- */
async function rbFinance(H: RbHelpers) {
  const L = 'rb-finance'
  const { both, sides } = H
  for (const who of ['santosh', 'priya', 'hritesh', 'ananya']) {
    await both(L, who, 'GET', '/finance/ledger')
    await both(L, who, 'GET', '/finance/ledger', undefined, { from: '2026-04-01', to: '2027-03-31', q: 'rent' })
    await both(L, who, 'GET', '/finance/ledger/entries', undefined, { scope: 'all' })
    await both(L, who, 'GET', '/finance/projects-lite')
    await both(L, who, 'GET', '/finance/pnl', undefined, { from: '2026-04-01', to: '2027-03-31' })
  }
  await both(L, 'santosh', 'GET', '/finance/pnl', undefined, { from: '2026-10-31', to: '2026-10-01' })
  for (const body of [{}, { kind: 'income' }, { kind: 'income', category: 'Consulting', description: 'Retainer', amount_paise: '100', date: TODAY() }, { kind: 'income', category: 'Consulting', description: 'Retainer', amount_paise: 100, date: TODAY(), status: 'paid' },
    { kind: 'expense', category: 'Rent', description: 'Rent', amount_paise: 100, date: TODAY(), recurring: true, until_on: '2020-01-01' }])
    await both(L, 'santosh', 'POST', '/finance/ledger', body)
  await both(L, 'priya', 'POST', '/finance/ledger', { kind: 'expense', category: 'Rent', description: 'Rent', amount_paise: 100, date: TODAY() })
  const e1 = await both(L, 'santosh', 'POST', '/finance/ledger', { kind: 'income', category: ' Consulting ', description: '  Monthly retainer ', amount_paise: 2500000, date: '2026-08-01', recurring: true, until_on: '2027-01-31', stream: 'services', project_id: 'p_hrms' })
  const eid = pick(e1, (d) => d.id)
  await sides(L, 'santosh', 'PATCH', (s) => `/finance/ledger/${eid(s)}`, () => ({ amount_paise: 2600000, description: ' Retainer v2 ' }))
  await sides(L, 'santosh', 'PATCH', (s) => `/finance/ledger/${eid(s)}`, () => ({ recurring: false, stream: '' }))
  await sides(L, 'santosh', 'PATCH', (s) => `/finance/ledger/${eid(s)}`, () => ({ status: 'paid' }))
  await both(L, 'santosh', 'GET', '/finance/ledger/entries')
  await sides(L, 'santosh', 'DELETE', (s) => `/finance/ledger/${eid(s)}`, () => undefined)
  const lk = await both(L, 'santosh', 'GET', '/finance/ledger', undefined, { from: '2026-04-01', to: '2027-03-31' })
  // locked rows (ids generated by each side's seed): the first locked row of the year on each side
  const lockedOf = (s: 'm' | 'h') => (((lk[s] as Res).data as any)?.items ?? []).find((x: any) => x.locked)
  const amt = lockedOf('m')?.amount_paise ?? 0
  await sides(L, 'santosh', 'PATCH', (s) => `/finance/ledger/${lockedOf(s)?.id ?? 'x'}`, () => ({ amount_paise: amt + 1 }))
  await sides(L, 'santosh', 'PATCH', (s) => `/finance/ledger/${lockedOf(s)?.id ?? 'x'}`, () => ({ amount_paise: amt, description: 'Renamed locked row' }))
  await sides(L, 'santosh', 'DELETE', (s) => `/finance/ledger/${lockedOf(s)?.id ?? 'x'}`, () => undefined)
  await both(L, 'santosh', 'GET', '/finance/pnl')
}

/* ---------------------------------------------------------------- spend ---------------------------------------------------------------- */
