  const { both, sides } = H
  const file = { name: 'r.pdf', mime: 'application/pdf', size_bytes: 1000, data_url: 'data:application/pdf;base64,JVBERi0xLjQKJcfsj6IKMSAwIG9iago8PD4+CmVuZG9iagp0cmFpbGVyCjw8Pj4KJSVFT0YK' }
